    cols = len(grid[0])
    goal_state_value = grid[-1][-1]

    visited_states = set()

    # Define valid movements (cardinal directions)
    movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    state_groups = [[[] for _ in range(cols)] for _ in range(rows)]
    current_group_index = 0

    def backtrack(state_value, current_state_group_index):
        nonlocal current_group_index
        visited_states.add(state_value)

        x, y = state_to_position(state_value)

        # Group adjacent states that have not been visited yet into the same group
        for dx, dy in movements:
            new_x, new_y = x + dx, y + dy

            if 0 <= new_x < rows and 0 <= new_y < cols:
                new_state_value = grid[new_x][new_y]

                # If adjacent state has not been visited yet and is not the goal
                if new_state_value != goal_state_value and new_state_value not in visited_states:
                    group_index = get_group_index(new_state_value, current_group_index)

                    # Add new state to its corresponding group
                    state_groups[group_index][0].append(new_state_value)

                    # If new state has more than one adjacent states (i.e., it's part of a cycle),
                    # then continue the backtracking from this state.
                    if len(state_groups[group_index]) > 1:
